// French editorial copy; itinerary order, media order and package IDs follow the
// published English products. Prices remain in the shared product catalogue.
const exclusions = [
  "Vols internationaux et intérieurs",
  "Déjeuners et dîners",
  "Assurance voyage personnelle, visas, pourboires et dépenses personnelles",
  "Surclassements et chambres individuelles supplémentaires",
  "Suppléments liés aux jours fériés, aux prestations de nuit, aux dépassements horaires ou à des prestations hors de l’itinéraire réservé",
] as const;
const booking = "Les tarifs de départ par personne concernent les groupes de 2, 4 et 6 voyageurs, hors vols. Pour un autre nombre de voyageurs, nous établissons un devis personnalisé. Indiquez vos dates, vos besoins en chambres, vos horaires d’arrivée et le nombre de bagages : nous vérifierons les disponibilités et vous remettrons le devis définitif avant paiement.";
const standardPackage = [{ id: "standard-guided", label: "Circuit privé", summary: "Véhicule privé, visites avec guide anglophone, transferts d’arrivée et de départ, billets d’entrée pour adultes prévus au programme et hébergement avec petit-déjeuner. Aucun passage imposé dans des boutiques." }] as const;
const days = (rows: readonly (readonly [string, string])[]) => rows.map(([title, description]) => ({ title, description }));
const media = (rows: readonly (readonly [number, string, string, string])[]) => {
  const result: { day: number; variants: { label: string; alt: string; caption: string }[] }[] = [];
  for (const [day, label, alt, caption] of rows) {
    let item = result.find(entry => entry.day === day);
    if (!item) { item = { day, variants: [] }; result.push(item); }
    item.variants.push({ label, alt, caption });
  }
  return result;
};
const qa = (rows: readonly (readonly [string, string])[]) => rows.map(([question, answer]) => ({ question, answer }));

